-								INDIGO_PRINTF(handle, "Content-Type: text/plain\r\n");
-								INDIGO_PRINTF(handle, "\r\n");
-								INDIGO_PRINTF(handle, "Out of buffer memory!\r\n");
-								INDIGO_TRACE(indigo_trace("%d <- // Out of buffer memory", handle->index));
+							void *content = content_length ? malloc(content_length) : NULL;
+							if (content_length && content == NULL) {
+								INDIGO_PRINTF(handle, "HTTP/1.1 503 Service Unavailable\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
 								goto failure;
 							}
+							free_on_exit = content;
+							handle->log_level = -abs(handle->log_level);
+							long received = content_length ? indigo_uni_read(handle, content, content_length) : 0;
+							handle->log_level = abs(handle->log_level);
+							if (received != content_length) {
+								INDIGO_PRINTF(handle, "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
+								goto failure;
+							}
+							free(entry->content);
+							entry->content = content;
+							entry->size = content_length;
+							free_on_exit = NULL;
+							pthread_mutex_unlock(&entry->mutext);
